import{_ as t,o,c as a,a4 as s}from"./chunks/framework.bruR1JhL.js";const p=JSON.parse('{"title":"Convert from PDF","description":"Turn a PDF into a Word document, a PowerPoint presentation, an Excel workbook, images or Markdown.","frontmatter":{"title":"Convert from PDF","description":"Turn a PDF into a Word document, a PowerPoint presentation, an Excel workbook, images or Markdown."},"headers":[],"relativePath":"docs/from-pdf.md","filePath":"docs/from-pdf.md","lastUpdated":1795509372000}'),r={name:"docs/from-pdf.md"};function n(i,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="convert-from-pdf" tabindex="-1">Convert from PDF <a class="header-anchor" href="#convert-from-pdf" aria-label="Permalink to &quot;Convert from PDF&quot;">​</a></h1><p>These tools turn a PDF into something you can edit or reuse: a Word document, a PowerPoint presentation, an Excel workbook, image files or a Markdown file. They never change the PDF itself.</p><p>Each tool starts with <strong>Choose a PDF to work on</strong>. Click <strong>Open PDF…</strong>, click <strong>Use</strong> followed by the file name to take the PDF selected in the Explorer, or drag a PDF from the Explorer onto the tool. You can also right-click a PDF in the Explorer and choose <strong>Convert from PDF</strong>, which opens it in the conversion tool you used last. The bar above the tool shows the file&#39;s name, page count and size, with <strong>Change…</strong> and <strong>Close</strong>. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer and the other general controls.</p><p>The open PDF is shared with most of the other PDF tools, so you can switch between them without opening it again. While a conversion runs, a progress bar shows how far it has got. When it finishes, a <strong>Saved</strong> card lists the new file with <strong>Open</strong> and <strong>Show in folder</strong>. When PDF to JPG makes a single picture, <strong>Keep editing this file</strong> opens it in the <a href="/tilepress/docs/img-edit#photo-editor">Photo editor</a>.</p><div class="tip custom-block"><p class="custom-block-title">Page ranges</p><p>Where a tool has a <strong>Pages</strong> field, leave it empty for every page, or type pages and ranges separated by commas: <code>1-3, 5, 8-</code>. <code>8-</code> means page 8 to the end and <code>-4</code> means pages 1 to 4. You can also type <code>odd</code>, <code>even</code> or <code>all</code>.</p></div><h2 id="pdf-to-word" tabindex="-1">PDF to Word <a class="header-anchor" href="#pdf-to-word" aria-label="Permalink to &quot;PDF to Word&quot;">​</a></h2><p>Turns a PDF into an editable Word document. Use it when you need to change the text of a document you only have as a PDF.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open a PDF.</li><li>Pick a <strong>Converter</strong> and a <strong>Format</strong>.</li><li>Click <strong>Convert to Word…</strong>.</li><li>Choose where to save the document in the Save dialog.</li></ol><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Converter</strong></td><td><strong>Microsoft Word (keeps the layout)</strong> uses Word&#39;s own PDF import. <strong>Built-in (text, headings, lists, tables)</strong> rebuilds the text and its structure without Word.</td><td>Microsoft Word when it&#39;s installed, otherwise Built-in</td></tr><tr><td><strong>Format</strong></td><td><strong>Word document (.docx)</strong> or <strong>Word 97–2003 (.doc)</strong>. The <code>.doc</code> format needs Microsoft Word, so it can&#39;t be picked with the built-in converter.</td><td>Word document (.docx)</td></tr></tbody></table><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The <strong>Microsoft Word</strong> choice only appears when Word is installed. Word runs hidden in the background with macros disabled and opens the PDF read-only. Word reflows the PDF into an editable document, so complex layouts may shift a little.</li><li>The built-in converter keeps the text and its structure only: headings (guessed from font size and bold text, up to four levels), paragraphs, bulleted and numbered lists, and tables. Images and exact positions are not kept. Each PDF page ends with a page break.</li><li>The Save dialog suggests the PDF&#39;s name with <code>.docx</code> (or <code>.doc</code>) in the same folder. If that name is taken, it adds a number, as in <code>report (2).docx</code>.</li><li>Scanned PDFs have no text to convert. Run <a href="/tilepress/docs/edit">OCR PDF</a> on them first.</li></ul><h2 id="pdf-to-powerpoint" tabindex="-1">PDF to PowerPoint <a class="header-anchor" href="#pdf-to-powerpoint" aria-label="Permalink to &quot;PDF to PowerPoint&quot;">​</a></h2><p>Makes a presentation with one slide per page. Each slide shows its page exactly, as a picture, and the page&#39;s text can go into the speaker notes.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open a PDF.</li><li>Choose the <strong>Slide image quality</strong>, and whether to put each page&#39;s text into the notes.</li><li>Click <strong>Convert to PowerPoint…</strong>.</li><li>Choose where to save the presentation.</li></ol><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Slide image quality</strong></td><td>How sharp the page pictures are: <strong>Smaller file</strong> (110 dpi), <strong>Standard</strong> (150 dpi) or <strong>High (large screens, printing)</strong> (220 dpi). Higher quality makes a bigger file.</td><td>Standard</td></tr><tr><td><strong>Put each page&#39;s text into the slide notes</strong></td><td>Copies the text of each page into that slide&#39;s speaker notes.</td><td>On</td></tr></tbody></table><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The slides take the size and shape of the first page. Pages with a different shape are fitted inside the slide and centred.</li><li>Very large pages are scaled down to PowerPoint&#39;s maximum slide size (56 inches).</li><li>The slides are pictures, so you can&#39;t edit the page text on the slide itself. Use the notes, or <a href="#pdf-to-word">PDF to Word</a>, to get at the text.</li><li>The Save dialog suggests the PDF&#39;s name with <code>.pptx</code> in the same folder.</li><li>Microsoft PowerPoint is not needed.</li></ul><h2 id="pdf-to-excel" tabindex="-1">PDF to Excel <a class="header-anchor" href="#pdf-to-excel" aria-label="Permalink to &quot;PDF to Excel&quot;">​</a></h2><p>Finds the tables in a PDF and puts each one on its own sheet. Numbers, percentages and amounts become real numbers you can calculate with.</p><h3 id="how-to-use-it-2" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open a PDF.</li><li>Type the <strong>Pages</strong> to search, or leave the field empty for all of them.</li><li>Choose how to <strong>Find tables by</strong>.</li><li>Click <strong>Convert to Excel…</strong>.</li><li>Choose where to save the workbook.</li></ol><h3 id="options-2" tabindex="-1">Options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Pages</strong></td><td>The pages to look for tables on.</td><td>All pages</td></tr><tr><td><strong>Find tables by</strong></td><td><strong>Ruled lines (grid tables)</strong> finds tables drawn with lines. <strong>Aligned text (tables without lines)</strong> finds columns of text that line up. <strong>Automatic</strong> looks for ruled tables first, and on a page that has none, looks for aligned text.</td><td>Automatic</td></tr></tbody></table><h3 id="good-to-know-2" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-2" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Each table gets its own sheet, named after its page: <code>Page 3</code>, or <code>Page 3 (1)</code>, <code>Page 3 (2)</code> when a page has several tables.</li><li>The first row of each sheet is bold and frozen, and the columns are sized to their content.</li><li>Cells that look like numbers are stored as numbers. This includes thousands separators in both styles (<code>1,234.50</code> and <code>1.234,50</code>), currency signs ($, €, £, ¥), negative amounts in brackets (<code>(12)</code> becomes -12) and percentages (<code>15%</code> becomes 0.15).</li><li>If no tables are found on the chosen pages, nothing is saved and the tool tells you so. Try the other <strong>Find tables by</strong> settings.</li><li>Scanned PDFs have no text to find. Run <a href="/tilepress/docs/edit">OCR PDF</a> on them first.</li><li>The Save dialog suggests the PDF&#39;s name with <code>.xlsx</code> in the same folder. Microsoft Excel is not needed.</li></ul><h2 id="pdf-to-jpg" tabindex="-1">PDF to JPG <a class="header-anchor" href="#pdf-to-jpg" aria-label="Permalink to &quot;PDF to JPG&quot;">​</a></h2><p>Saves pages as image files, or pulls out the pictures embedded in the PDF.</p><h3 id="how-to-use-it-3" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-3" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open a PDF.</li><li>Choose <strong>Pages as images</strong> or <strong>Extract embedded images</strong> at the top.</li><li>Set the options, and choose where to save: <strong>Save next to each PDF</strong> or <strong>Save in a folder</strong> (click <strong>Choose…</strong> to pick the folder).</li><li>Click <strong>Save images</strong> (or <strong>Extract images</strong>).</li></ol><p>There is no Save dialog: the files go straight to the place you chose, and the <strong>Saved</strong> card lists them.</p><h3 id="options-3" tabindex="-1">Options <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Pages as images</strong> / <strong>Extract embedded images</strong></td><td>Draw each page as a picture, or save the pictures that are inside the pages.</td><td>Pages as images</td></tr><tr><td><strong>Pages</strong></td><td>The pages to save or to take pictures from.</td><td>All pages</td></tr><tr><td><strong>Format</strong></td><td><strong>JPG</strong> or <strong>PNG (lossless)</strong>. Pages as images only.</td><td>JPG</td></tr><tr><td><strong>Resolution</strong></td><td>72, 96, 150, 220, 300 or 600 dpi. The size in pixels of the first page is shown underneath. Pages as images only.</td><td>150 dpi</td></tr><tr><td><strong>JPG quality</strong></td><td>40 to 100. Higher keeps more detail and makes bigger files. JPG only.</td><td>90</td></tr><tr><td><strong>Save next to each PDF</strong> / <strong>Save in a folder</strong></td><td>Where the images go.</td><td>Next to the PDF</td></tr></tbody></table><h3 id="good-to-know-3" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-3" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Pages are named after the PDF and the page number: <code>report_p1.jpg</code>, <code>report_p2.jpg</code> and so on. Extracted pictures add a number for each picture on the page: <code>report_p3_1.jpg</code>, <code>report_p3_2.png</code>.</li><li>Existing files are never overwritten: a number is added instead, as in <code>report_p1 (2).jpg</code>.</li><li>Extracted pictures keep their original size and the format they are stored in, so you may get a mix of file types. A picture that appears on several pages, such as a logo, is saved once for each page.</li><li>If the chosen pages have no embedded pictures, the tool tells you and saves nothing.</li><li>In <a href="/tilepress/docs/history">History</a>, runs that saved PNG files are listed as &quot;PDF to PNG&quot;.</li></ul><h2 id="pdf-to-markdown" tabindex="-1">PDF to Markdown <a class="header-anchor" href="#pdf-to-markdown" aria-label="Permalink to &quot;PDF to Markdown&quot;">​</a></h2><p>Turns the PDF&#39;s text and structure into Markdown: headings, paragraphs, lists and tables. A preview shows the result before you save.</p><h3 id="how-to-use-it-4" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-4" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open a PDF.</li><li>Type the <strong>Pages</strong> to convert, or leave the field empty for all of them.</li><li>Check the preview below the options. Tick <strong>Show Markdown source</strong> to see the raw Markdown instead of the rendered page.</li><li>Click <strong>Save as Markdown…</strong> and choose where to save the file.</li></ol><h3 id="options-4" tabindex="-1">Options <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Pages</strong></td><td>The pages to convert.</td><td>All pages</td></tr><tr><td><strong>Mark page breaks with comments</strong></td><td>Adds a line such as <code>&lt;!-- page 2 --&gt;</code> where each new page starts. These comments don&#39;t show when the Markdown is displayed.</td><td>Off</td></tr><tr><td><strong>Show Markdown source</strong></td><td>Switches the preview between the rendered result and the Markdown text. It doesn&#39;t change the saved file.</td><td>Off</td></tr></tbody></table><h3 id="good-to-know-4" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-4" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The preview shows the first five of the chosen pages, to stay quick. The saved file contains every chosen page.</li><li>Headings are guessed from font size and bold text, and get up to four levels (<code>#</code> to <code>####</code>). Numbered lists are renumbered from 1. Tables become Markdown tables.</li><li>Images are not included.</li><li>Scanned PDFs have no text to convert. Run <a href="/tilepress/docs/edit">OCR PDF</a> on them first.</li><li>The Save dialog suggests the PDF&#39;s name with <code>.md</code> in the same folder.</li></ul><div class="warning custom-block"><p class="custom-block-title">Password-protected PDFs</p><p>These tools can&#39;t open a PDF that needs a password. Unlock a copy with <a href="/tilepress/docs/security">Protect PDF</a> first.</p></div>',47)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
